{
  "summary": [
    {
      "text": "Накопленная добыча за время t пропорциональна квадратному корню из времени.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Скорость роста добычи со временем падает, хотя общий объем продолжает увеличиваться.",
      "claims": [
        "c2"
      ]
    }
  ],
  "how_it_works": [
    {
      "text": "Накопленная добыча V_доб определяется интегралом от дебита Q(t) по времени.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "Для упругого режима дебита Q(t) зависит от времени как 1/sqrt(t).",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "Интегрирование функции 1/sqrt(t) дает результат, пропорциональный sqrt(t).",
      "claims": [
        "c5"
      ]
    },
    {
      "text": "Коэффициент пропорциональности включает проницаемость k, перепад давлений, толщину h и вязкость.",
      "claims": [
        "c6"
      ]
    },
    {
      "text": "В результате получается формула V_доб = C * sqrt(t), где C — константа для данных условий.",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "Сразу после начала отбора добыча быстро возрастает.",
      "claims": [
        "c8"
      ]
    },
    {
      "text": "В дальнейшем рост добычи происходит очень медленно.",
      "claims": [
        "c9"
      ]
    }
  ],
  "steps": [
    {
      "text": "Зафиксировать дебит Q(t) в момент времени t.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "Проинтегрировать дебит от 0 до t для получения объема.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "Применить аналитическое решение для упругого режима.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "Получить зависимость объема от sqrt(t).",
      "claims": [
        "c7"
      ]
    }
  ],
  "examples": [],
  "numbers": [
    {
      "text": "Коэффициент перед sqrt(t) содержит множитель 2.",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "В знаменателе формулы присутствует pi.",
      "claims": [
        "c7"
      ]
    }
  ],
  "formulas": [
